typedef struct { int *data; size_t len, cap; } Vec;
int push(Vec *v, int x) {
  if (v->len == v->cap) {
    size_t nc = v->cap ? v->cap * 2 : 4;
    int *t = realloc(v->data, nc * sizeof *t);
    if (!t) return -1;
    v->data = t; v->cap = nc;
  }
  v->data[v->len++] = x; return 0;
}
